// The Heads of Terms flow on a Letting Tracker unit (Woody, 2026-11-12;
// shared/unit-hots.ts, migration 0051). Routes are registered from
// server/index.ts.
//
// A property has a STANDARD set of HOTs (created from BGP's standard, typed,
// or read from an uploaded Word document). Once an offer's terms are agreed
// the unit's HOTs are GENERATED by filling the standard from that offer, the
// unit and its Targeting Brief. The people on the brief amend the draft (each
// amendment raises the version) and each agrees the current version. BGP
// then records the HOTs as ISSUED. The negotiation on the HOTs themselves
// happens outside the app; the FINAL agreed HOTs are uploaded and the letting
// is CONVERTED to Solicitors, which puts the agreed terms on the deal.
//
// Who may do what is briefAccess() (server/unit-brief-workspace.ts): BGP
// staff everywhere, a client login on its own properties, a Landsec asset
// manager or joint agent on their own schemes; a joint agent reads and
// agrees but never changes the text. The standard, issuing, the final upload
// and the conversion are BGP's.
import type { Express, Request, Response, RequestHandler } from "express";
import path from "path";
import crypto from "crypto";
import { pool } from "./db";
import { requireAuth } from "./auth";
import { storage } from "./storage";
import multer from "./utils/upload";
import { saveFile } from "./file-storage";
import { contentDispositionFor } from "./utils/http-headers";
import { briefAccess } from "./unit-brief-workspace";
import { BRIEF_PERSON_ROLES, briefRoleLabel, normaliseCommercials, parseMoney } from "@shared/unit-brief";
import { legacyToCode, DEAL_STATUS_LABELS } from "@shared/deal-status";
import {
  HOTS_TOKENS, STANDARD_HOTS_TEMPLATE, fillHotsTemplate, hotsGapsIn,
  type HotsConversion, type HotsConvertDefaults, type HotsEvent, type HotsSigner, type HotsStage, type HotsValues, type HotsWorkspace,
} from "@shared/unit-hots";

type Access = NonNullable<Awaited<ReturnType<typeof briefAccess>>>;
type Db = { query: (sql: string, params?: any[]) => Promise<any> };

const TEMPLATE_MAX = 60_000;
const CONTENT_MAX = 120_000;
const DOCX_MIME = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
const AGREED_OFFER_SQL = `lower(trim(coalesce(status, ''))) IN ('agreed', 'accepted')`;
// At Solicitors or past it: the letting has been converted.
const CONVERTED_CODES = ["SOL", "EXC", "COM", "INV"];

const iso = (d: any): string | null => (d ? new Date(d).toISOString() : null);
const text = (v: any): string => (typeof v === "string" ? v : "");
const hasText = (v: any): boolean => text(v).trim() !== "";
const sameEmail = (a: any, b: any) => !!a && !!b && String(a).trim().toLowerCase() === String(b).trim().toLowerCase();
const isAgreedStatus = (s: any) => ["agreed", "accepted"].includes(String(s || "").trim().toLowerCase());
const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;
const listNames = (names: string[]): string =>
  names.length <= 1 ? names.join("") : `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;

const gbp = (n: any): string => `£${Number(n).toLocaleString("en-GB", { maximumFractionDigits: 2 })}`;
const num = (n: any): string => Number(n).toLocaleString("en-GB", { maximumFractionDigits: 2 });
const longDate = (d: Date): string => d.toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "Europe/London" });
// "2026-11-10" -> "10 Nov 2026"; anything else is shown as written.
const shortDate = (s: any): string => {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s || ""));
  if (!m) return String(s || "");
  return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
};

async function loadUnit(unitId: string, db: Db = pool): Promise<any | null> {
  return (await db.query(
    `SELECT au.id, au.unit_name, au.property_id, au.sqft, au.use_class, au.service_charge_pa, au.rates_pa, au.marketing_status, au.deal_id,
            au.hots_content, au.hots_updated_at, COALESCE(au.hots_version, 0) AS hots_version, au.hots_offer_id, au.hots_agreed_at,
            au.hots_issued_at, au.hots_issued_by_name, au.hots_final_file_id, au.hots_final_at, au.hots_final_by_name,
            p.name AS property_name, p.landlord_id, p.hots_template, p.hots_template_docx, p.hots_template_docx_name,
            lc.name AS landlord_name, d.deal_ref,
            f.id AS final_id, f.file_name AS final_name, f.file_path AS final_path
       FROM available_units au
       LEFT JOIN crm_properties p ON p.id = au.property_id
       LEFT JOIN crm_companies lc ON lc.id = p.landlord_id
       LEFT JOIN crm_deals d ON d.id = au.deal_id
       LEFT JOIN unit_marketing_files f ON f.id = au.hots_final_file_id AND f.unit_id = au.id
      WHERE au.id = $1`, [unitId])).rows[0] || null;
}

// The unit, and whether the person asking may open it. Answers 404 / 403
// itself and returns null when they may not.
async function openUnit(req: Request, res: Response): Promise<{ unit: any; access: Access } | null> {
  const unit = await loadUnit(String(req.params.unitId));
  if (!unit) { res.status(404).json({ message: "That unit is not on the tracker" }); return null; }
  const access = await briefAccess(req, unit.property_id);
  if (!access) { res.status(403).json({ message: "This unit is outside your access" }); return null; }
  return { unit, access };
}

// The people who sign off the HOTs: the people on the unit's Targeting Brief.
async function briefAndPeople(unitId: string): Promise<{ brief: any | null; people: any[] }> {
  const brief = (await pool.query(`SELECT id, commercials FROM unit_briefs WHERE unit_id = $1 ORDER BY created_at DESC LIMIT 1`, [unitId])).rows[0] || null;
  if (!brief) return { brief: null, people: [] };
  const people = (await pool.query(
    `SELECT id, role, user_id, name, email, firm, sort_order, created_at FROM unit_brief_people WHERE brief_id = $1 ORDER BY sort_order, created_at`, [brief.id])).rows;
  const order = (role: string) => { const i = BRIEF_PERSON_ROLES.findIndex(r => r.key === role); return i < 0 ? 99 : i; };
  people.sort((a: any, b: any) => order(a.role) - order(b.role));
  return { brief, people };
}

const isSelfPerson = (p: any, access: Access): boolean => (p.user_id ? p.user_id === access.userId : sameEmail(p.email, access.email));

function roleLabelFor(people: any[], access: Access): string {
  const mine = people.find(p => isSelfPerson(p, access));
  if (mine) return mine.role === "joint_agent" && mine.firm ? `Joint agent · ${mine.firm}` : briefRoleLabel(mine.role);
  if (access.isStaff) return "BGP";
  if (access.landsecRole === "asset_manager") return "Asset manager";
  if (access.landsecRole === "joint_agent") return "Joint agent";
  return access.scopeName || "Client";
}

async function logEvent(unitId: string, access: Access, people: any[], kind: string, body: string, version: number | null) {
  await pool.query(
    `INSERT INTO unit_hots_events (unit_id, kind, body, version, author_user_id, author_name, author_role) VALUES ($1, $2, $3, $4, $5, $6, $7)`,
    [unitId, kind, body, version, access.userId, access.name, roleLabelFor(people, access)],
  ).catch((e: any) => console.warn("[unit-hots] event log failed:", e?.message));
}

// One HOTs write on a unit at a time. The connection holds only the lock;
// the work runs on the pool (the status mirror and the deal door do too).
async function withUnitLock<T>(unitId: string, fn: () => Promise<T>): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [`unit_hots:${unitId}`]);
    return await fn();
  } finally {
    await client.query("COMMIT").catch(() => undefined);
    client.release();
  }
}

// available_units.hots_agreed_at follows the signatures: set while there is
// a draft, at least one person is on the brief and every one of them has a
// signature on the current version; cleared otherwise. One statement, so an
// amendment cannot slip between the read and the write.
async function refreshAgreed(unitId: string): Promise<void> {
  await pool.query(
    `UPDATE available_units au SET hots_agreed_at = CASE
        WHEN trim(coalesce(au.hots_content, '')) <> ''
         AND EXISTS (SELECT 1 FROM unit_brief_people p WHERE p.brief_id = b.id)
         AND NOT EXISTS (
               SELECT 1 FROM unit_brief_people p WHERE p.brief_id = b.id
                  AND NOT EXISTS (SELECT 1 FROM unit_hots_signoffs s
                                   WHERE s.unit_id = au.id AND s.brief_person_id = p.id AND s.version = COALESCE(au.hots_version, 0)))
        THEN COALESCE(au.hots_agreed_at, NOW())
        ELSE NULL END
       FROM (SELECT $1::varchar AS unit_id, (SELECT id FROM unit_briefs WHERE unit_id = $1 ORDER BY created_at DESC LIMIT 1) AS id) b
      WHERE au.id = b.unit_id`, [unitId]);
}

async function agreedOfferFor(unitId: string): Promise<any | null> {
  return (await pool.query(
    `SELECT * FROM unit_offers WHERE unit_id = $1 AND ${AGREED_OFFER_SQL}
      ORDER BY agreed_at DESC NULLS LAST, updated_at DESC NULLS LAST, created_at DESC NULLS LAST LIMIT 1`, [unitId])).rows[0] || null;
}
async function offerById(id: string | null | undefined): Promise<any | null> {
  return id ? (await pool.query(`SELECT * FROM unit_offers WHERE id = $1`, [id])).rows[0] || null : null;
}

function stageOf(unit: any): HotsStage {
  if (unit.final_id) return "final";
  if (unit.hots_issued_at) return "issued";
  if (hasText(unit.hots_content)) return unit.hots_agreed_at ? "agreed" : "draft";
  if (hasText(unit.hots_template) || unit.hots_template_docx) return "no_draft";
  return "no_template";
}

// `recorderEmails` maps the logins that recorded a signature to their email:
// a person with no login on their brief row who signed in and agreed (matched
// by email) agreed for themselves, not through someone else.
function signersOf(unit: any, people: any[], signoffs: any[], access: Access, recorderEmails: Map<string, string>): HotsSigner[] {
  const draft = hasText(unit.hots_content);
  return people.map((p: any) => {
    const s = signoffs.find((x: any) => x.brief_person_id === p.id);
    const current = !!s && draft && s.version === unit.hots_version;
    const bySelf = !!s && (p.user_id ? s.agreed_by_user_id === p.user_id : sameEmail(recorderEmails.get(s.agreed_by_user_id), p.email));
    return {
      briefPersonId: p.id, role: p.role, name: p.name, firm: p.firm || null, userId: p.user_id || null,
      isMe: isSelfPerson(p, access),
      agreedAt: current ? iso(s.agreed_at) : null,
      staleAgreedAt: s && !current ? iso(s.agreed_at) : null,
      agreedByName: s ? s.agreed_by_name || null : null,
      agreedOnBehalf: !!s && !bySelf,
    };
  });
}

async function amlLineFor(dealId: string): Promise<{ deal: any; aml: { ok: boolean; message: string | null } }> {
  const deal = (await pool.query(
    `SELECT d.id, d.deal_ref, d.status, d.tenant_id, d.landlord_id, d.vendor_id, d.purchaser_id, tc.name AS tenant_name
       FROM crm_deals d LEFT JOIN crm_companies tc ON tc.id = d.tenant_id WHERE d.id = $1`, [dealId])).rows[0];
  if (!deal) return { deal: null, aml: { ok: false, message: "The deal could not be read." } };
  try {
    const { checkCounterpartyAml, formatAmlWarning } = await import("./deal-gates");
    const result = await checkCounterpartyAml({ landlordId: deal.landlord_id, tenantId: deal.tenant_id, vendorId: deal.vendor_id, purchaserId: deal.purchaser_id });
    const message = formatAmlWarning(result);
    return { deal, aml: { ok: !message, message } };
  } catch (e: any) {
    return { deal, aml: { ok: false, message: `AML could not be checked (${e?.message || "error"}).` } };
  }
}

async function conversionFor(unit: any, access: Access, statusWarning?: string | null): Promise<HotsConversion | null> {
  if (!unit.deal_id) return null;
  const { deal, aml } = await amlLineFor(unit.deal_id);
  if (!deal) return null;
  return {
    dealId: deal.id, dealRef: deal.deal_ref ?? null,
    // Landsec asset managers and joint agents have no deal page.
    dealUrl: access.landsecRole === "asset_manager" || access.landsecRole === "joint_agent" ? null : `/deals/${deal.id}`,
    tenantCompanyId: access.isStaff ? deal.tenant_id || null : null,
    tenantName: deal.tenant_name || null,
    aml,
    ...(statusWarning ? { statusWarning } : {}),
  };
}

// The terms a conversion starts from: the offer the HOTs came from, else the
// unit's agreed offer. The tenant is the offer's CRM company when it has one.
async function convertDefaultsFor(unit: any): Promise<HotsConvertDefaults> {
  const offer = (await offerById(unit.hots_offer_id)) || (await agreedOfferFor(unit.id));
  const dealTenant = unit.deal_id
    ? (await pool.query(`SELECT d.tenant_id, c.name FROM crm_deals d JOIN crm_companies c ON c.id = d.tenant_id WHERE d.id = $1`, [unit.deal_id])).rows[0] || null
    : null;
  let tenantCompanyId: string | null = null, tenantName: string | null = null;
  if (offer?.company_id) {
    const c = (await pool.query(`SELECT id, name FROM crm_companies WHERE id = $1`, [offer.company_id])).rows[0];
    if (c) { tenantCompanyId = c.id; tenantName = c.name; }
  }
  if (!tenantCompanyId && dealTenant) { tenantCompanyId = dealTenant.tenant_id; tenantName = dealTenant.name; }
  return {
    tenantCompanyId, tenantName: tenantName || offer?.company_name || null,
    rentPa: offer?.rent_pa ?? null, leaseLengthYears: offer?.term_years ?? null, rentFreeMonths: offer?.rent_free_months ?? null,
    breakOption: offer?.break_option || null, capitalContribution: offer?.fitting_out_contribution ?? null,
  };
}

// Everything the HOTs dialog shows, in one read.
async function buildWorkspace(unitId: string, access: Access): Promise<HotsWorkspace> {
  let unit = await loadUnit(unitId);
  if (!unit) throw new Error("That unit is no longer on the tracker");
  const [{ brief, people }, signoffQ, eventsQ] = await Promise.all([
    briefAndPeople(unitId),
    pool.query(`SELECT * FROM unit_hots_signoffs WHERE unit_id = $1`, [unitId]),
    pool.query(`SELECT * FROM unit_hots_events WHERE unit_id = $1 ORDER BY created_at ASC, id ASC LIMIT 500`, [unitId]),
  ]);
  const recorderIds = [...new Set(signoffQ.rows.map((s: any) => s.agreed_by_user_id).filter(Boolean))];
  const recorderEmails = new Map<string, string>(recorderIds.length
    ? (await pool.query(`SELECT id, email FROM users WHERE id = ANY($1::varchar[])`, [recorderIds])).rows.map((u: any) => [u.id, u.email || ""] as [string, string])
    : []);
  const signers = signersOf(unit, people, signoffQ.rows, access, recorderEmails);
  const agreed = signers.filter(s => s.agreedAt).length;
  const complete = hasText(unit.hots_content) && signers.length > 0 && agreed === signers.length;
  // The stored date follows the people on the brief, who can change without
  // this module hearing of it: heal it here so the stage is never stale.
  if (complete !== !!unit.hots_agreed_at) {
    await refreshAgreed(unitId);
    unit = await loadUnit(unitId);
  }
  const stage = stageOf(unit);
  const [offer, agreedOffer] = await Promise.all([offerById(unit.hots_offer_id), agreedOfferFor(unitId)]);
  const converted = stage === "final" && CONVERTED_CODES.includes(legacyToCode(unit.marketing_status) || "");
  const content = hasText(unit.hots_content) ? text(unit.hots_content) : null;
  const events: HotsEvent[] = eventsQ.rows.map((e: any) => ({
    id: e.id, kind: e.kind, body: e.body, version: e.version, authorName: e.author_name, authorRole: e.author_role, createdAt: iso(e.created_at),
  }));
  return {
    unit: { id: unit.id, unitName: unit.unit_name, propertyId: unit.property_id || null, propertyName: unit.property_name || null,
      marketingStatus: unit.marketing_status || null, dealId: unit.deal_id || null, dealRef: unit.deal_ref ?? null },
    stage,
    template: { text: hasText(unit.hots_template) ? unit.hots_template : null, docxName: unit.hots_template_docx ? unit.hots_template_docx_name || "Standard HOTs.docx" : null,
      isStandard: text(unit.hots_template) === STANDARD_HOTS_TEMPLATE },
    content,
    version: unit.hots_version,
    updatedAt: iso(unit.hots_updated_at),
    gaps: content ? hotsGapsIn(content) : [],
    offer: offer && offer.unit_id === unitId ? { id: offer.id, companyName: offer.company_name || null, status: offer.status || "Pending", offerDate: offer.offer_date, rentPa: offer.rent_pa ?? null } : null,
    agreedOffer: agreedOffer ? { id: agreedOffer.id, companyName: agreedOffer.company_name || null, offerDate: agreedOffer.offer_date, rentPa: agreedOffer.rent_pa ?? null } : null,
    briefId: brief?.id || null,
    signers,
    approval: { total: signers.length, agreed, complete },
    agreedAt: iso(unit.hots_agreed_at),
    issuedAt: iso(unit.hots_issued_at), issuedByName: unit.hots_issued_by_name || null,
    finalFile: unit.final_id ? { id: unit.final_id, fileName: unit.final_name, url: unit.final_path, uploadedAt: iso(unit.hots_final_at), uploadedByName: unit.hots_final_by_name || null } : null,
    events,
    viewer: {
      isStaff: access.isStaff,
      canEdit: access.canEditTerms && stage !== "issued" && stage !== "final",
      canManageTemplate: access.isStaff, canIssue: access.isStaff, canConvert: access.isStaff,
    },
    convertDefaults: access.isStaff && stage === "final" && !converted ? await convertDefaultsFor(unit) : null,
    conversion: converted ? await conversionFor(unit, access) : null,
  };
}

// The known {TOKENS} a standard uses.
function knownTokensIn(template: string): string[] {
  const known = new Set<string>(HOTS_TOKENS.map(t => t.token));
  const out = new Set<string>();
  for (const m of template.matchAll(/\{([A-Z_]+)\}/g)) if (known.has(m[1])) out.add(m[1]);
  return [...out];
}

// What changed between two versions of the draft, in words a person can
// scan: up to three changed lines quoted, then a count of the rest.
export function describeHotsChange(before: string, after: string): string {
  const a = before.split("\n"), b = after.split("\n");
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) start++;
  let endA = a.length, endB = b.length;
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) { endA--; endB--; }
  const A = a.slice(start, endA), B = b.slice(start, endB);
  const changes: { was?: string; now?: string }[] = [];
  const flush = (removed: string[], added: string[]) => {
    const n = Math.max(removed.length, added.length);
    for (let k = 0; k < n; k++) {
      const was = k < removed.length ? removed[k] : undefined, now = k < added.length ? added[k] : undefined;
      // A blank line added or removed is spacing, not a change to the terms.
      if (!(was || "").trim() && !(now || "").trim()) continue;
      changes.push({ was, now });
    }
  };
  const n = A.length, m = B.length;
  if (n * m > 1_000_000) {
    flush(A, B);
  } else {
    // Longest common subsequence of the lines, so an inserted clause does
    // not make every line after it read as changed.
    const w = m + 1;
    const dp = new Uint16Array((n + 1) * w);
    for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) {
      dp[i * w + j] = A[i] === B[j] ? dp[(i + 1) * w + j + 1] + 1 : Math.max(dp[(i + 1) * w + j], dp[i * w + j + 1]);
    }
    let i = 0, j = 0, removed: string[] = [], added: string[] = [];
    while (i < n || j < m) {
      if (i < n && j < m && A[i] === B[j]) { flush(removed, added); removed = []; added = []; i++; j++; }
      else if (j < m && (i === n || dp[i * w + j + 1] >= dp[(i + 1) * w + j])) added.push(B[j++]);
      else removed.push(A[i++]);
    }
    flush(removed, added);
  }
  if (changes.length === 0) return "changed the spacing only";
  const q = (s: string | undefined) => { const t = (s || "").trim(); return `"${t.length > 160 ? `${t.slice(0, 159)}…` : t}"`; };
  const lines = changes.slice(0, 3).map(c =>
    (c.was || "").trim() && (c.now || "").trim() ? `was: ${q(c.was)} / now: ${q(c.now)}`
      : (c.now || "").trim() ? `added: ${q(c.now)}` : `removed: ${q(c.was)}`);
  if (changes.length > 3) lines.push(`and ${plural(changes.length - 3, "more line", "more lines")}`);
  return lines.join("\n");
}

// The values that fill the standard: the agreed offer first, then the unit,
// then the brief. A term the offer lacks falls back to the brief's
// commercials; where both lack it the gap placeholder stays in the draft.
async function hotsValuesFor(unit: any, offer: any, brief: any | null, people: any[]): Promise<HotsValues> {
  const c = normaliseCommercials(brief?.commercials).value;
  const money = (v: any, zero = "£0"): string | null => (v === null || v === undefined || !Number.isFinite(Number(v)) ? null : Number(v) === 0 ? zero : gbp(v));
  const term = offer.term_years ?? c.leaseTermYears;
  const lines = (rows: any[], f: (p: any) => string) => rows.map(f).join("\n") || null;
  return {
    PROPERTY: unit.property_name, UNIT: unit.unit_name,
    AREA: unit.sqft != null && Number(unit.sqft) > 0 ? `${num(unit.sqft)} sq ft` : null,
    DATE: longDate(new Date()),
    LANDLORD: unit.landlord_name,
    TENANT: offer.company_name, TENANT_CONTACT: offer.contact_name,
    RENT: money(offer.rent_pa),
    TURNOVER_RENT: offer.turnover_rent_pct != null && Number(offer.turnover_rent_pct) > 0 ? `${num(offer.turnover_rent_pct)}% of turnover` : null,
    TERM: term != null && Number(term) > 0 ? `${num(term)} ${Number(term) === 1 ? "year" : "years"}` : null,
    BREAK: offer.break_option || c.breakOption,
    RENT_FREE: offer.rent_free_months == null ? null : Number(offer.rent_free_months) === 0 ? "None" : `${num(offer.rent_free_months)} ${Number(offer.rent_free_months) === 1 ? "month" : "months"}`,
    CAPITAL_CONTRIBUTION: money(offer.fitting_out_contribution, "None"), FIT_OUT: money(offer.fitting_out_contribution, "None"),
    PREMIUM: money(offer.premium, "None"),
    RENT_REVIEW: offer.rent_review || c.rentReview,
    RENT_DEPOSIT: offer.rent_deposit, INCENTIVES: offer.incentives,
    OFFER_DATE: offer.offer_date ? shortDate(offer.offer_date) : null,
    SERVICE_CHARGE: money(unit.service_charge_pa), RATES: money(unit.rates_pa),
    INSURANCE: money(c.insurancePa), USE: c.permittedUse || unit.use_class,
    LANDLORD_AGENT: lines(people.filter(p => p.role === "bgp_agent"), p => [p.name, "Bruce Gillingham Pollard", p.email].filter(Boolean).join(", ")),
    JOINT_AGENT: lines(people.filter(p => p.role === "joint_agent"), p => [p.name, p.firm].filter(Boolean).join(", ")),
    LANDLORD_CONTACT: lines(people.filter(p => p.role === "client_leasing"), p => [p.name, p.email].filter(Boolean).join(", ")),
  };
}

// The text of a Word document, for a standard uploaded as .docx.
async function docxText(buffer: Buffer): Promise<string> {
  const mammoth: any = await import("mammoth");
  const out = await (mammoth.extractRawText || mammoth.default.extractRawText)({ buffer });
  return String(out?.value || "").replace(/\r\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
}

// One file from a multipart form, in memory. A wrong type or an oversized
// file answers 400 in plain words instead of a 500.
function oneFile(exts: string[], maxMb: number, wrongType: string): RequestHandler {
  const upload = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: maxMb * 1024 * 1024, files: 1 },
    fileFilter: (_req, file, cb) => {
      if (!exts.includes(path.extname(file.originalname || "").toLowerCase())) return cb(new Error(wrongType));
      cb(null, true);
    },
  }).single("file");
  return (req, res, next) => upload(req, res, (err?: any) => {
    if (!err) return next();
    const tooBig = err?.code === "LIMIT_FILE_SIZE";
    res.status(400).json({ message: tooBig ? `That file is too big. The limit is ${maxMb} MB.` : err?.message || "That file could not be read" });
  });
}

const fail = (res: Response, e: any, fallback: string) => {
  console.error("[unit-hots]", e?.message);
  res.status(500).json({ message: e?.message || fallback });
};
const STAFF_ONLY = "This is done by BGP";
const safeName = (s: any) => String(s || "").replace(/[/\\:*?"<>|]/g, "-").trim();

// Remove a unit's HOTs sign-offs and history (called when the unit is deleted).
export async function deleteUnitHots(unitId: string, db: Db = pool): Promise<void> {
  await db.query(`DELETE FROM unit_hots_signoffs WHERE unit_id = $1`, [unitId]);
  await db.query(`DELETE FROM unit_hots_events WHERE unit_id = $1`, [unitId]);
}

export function setupUnitHotsRoutes(app: Express) {
  // 1. Everything the dialog shows.
  app.get("/api/unit-hots/:unitId", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      res.json(await buildWorkspace(ctx.unit.id, ctx.access));
    } catch (e: any) { fail(res, e, "Failed to load the Heads of Terms"); }
  });

  // 2. The property's standard. BGP's to make and change: it is a shared
  // record, used by every unit on the property.
  app.post("/api/unit-hots/:unitId/template/standard", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { unit, access } = ctx;
      if (!access.isStaff) return res.status(403).json({ message: `${STAFF_ONLY}: BGP sets the standard Heads of Terms for a property` });
      if (!unit.property_id) return res.status(400).json({ message: "Link this unit to a property first" });
      await withUnitLock(`property:${unit.property_id}`, async () => {
        const now = (await pool.query(`SELECT hots_template FROM crm_properties WHERE id = $1`, [unit.property_id])).rows[0];
        if (hasText(now?.hots_template) && req.body?.replace !== true) {
          res.status(409).json({ message: "This property already has standard Heads of Terms. Replace them with BGP's standard?", code: "TEMPLATE_EXISTS" });
          return;
        }
        await pool.query(`UPDATE crm_properties SET hots_template = $1 WHERE id = $2`, [STANDARD_HOTS_TEMPLATE, unit.property_id]);
        const { people } = await briefAndPeople(unit.id);
        await logEvent(unit.id, access, people, "template", `${hasText(now?.hots_template) ? "replaced the property's standard Heads of Terms with" : "created the property's standard Heads of Terms from"} BGP's standard`, null);
        res.json(await buildWorkspace(unit.id, access));
      });
    } catch (e: any) { fail(res, e, "Failed to create the standard Heads of Terms"); }
  });

  app.put("/api/unit-hots/:unitId/template", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { unit, access } = ctx;
      if (!access.isStaff) return res.status(403).json({ message: `${STAFF_ONLY}: BGP sets the standard Heads of Terms for a property` });
      if (!unit.property_id) return res.status(400).json({ message: "Link this unit to a property first" });
      const raw = req.body?.text;
      if (raw !== null && raw !== undefined && typeof raw !== "string") return res.status(400).json({ message: "The standard Heads of Terms must be text" });
      const next = text(raw).replace(/\r\n/g, "\n");
      if (next.length > TEMPLATE_MAX) return res.status(400).json({ message: `The standard is too long (${num(next.length)} characters). The limit is ${num(TEMPLATE_MAX)}.` });
      const before = text(unit.hots_template);
      if (before !== next) {
        await pool.query(`UPDATE crm_properties SET hots_template = $1 WHERE id = $2`, [next.trim() ? next : null, unit.property_id]);
        const { people } = await briefAndPeople(unit.id);
        await logEvent(unit.id, access, people, "template", next.trim() ? "changed the property's standard Heads of Terms" : "cleared the property's standard Heads of Terms", null);
      }
      res.json(await buildWorkspace(unit.id, access));
    } catch (e: any) { fail(res, e, "Failed to save the standard Heads of Terms"); }
  });

  app.post("/api/unit-hots/:unitId/template/upload", requireAuth, oneFile([".docx"], 15, "Upload a Word document (.docx)"), async (req: any, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { unit, access } = ctx;
      if (!access.isStaff) return res.status(403).json({ message: `${STAFF_ONLY}: BGP sets the standard Heads of Terms for a property` });
      if (!unit.property_id) return res.status(400).json({ message: "Link this unit to a property first" });
      if (!req.file) return res.status(400).json({ message: "Choose a Word document (.docx) to upload" });
      let read = "";
      try { read = await docxText(req.file.buffer); }
      catch { return res.status(400).json({ message: "That Word document could not be read. Save it again as .docx and upload it." }); }
      if (!read) return res.status(400).json({ message: "No text could be read from that document, so it cannot be used as the standard. Use Create standard HOTs instead." });
      if (read.length > TEMPLATE_MAX) return res.status(400).json({ message: `That document is too long to use as a standard (${num(read.length)} characters of text). The limit is ${num(TEMPLATE_MAX)}.` });
      const name = String(req.file.originalname || "Standard HOTs.docx").slice(0, 200);
      // The same key and columns as the property's own upload route.
      const key = `hots-templates/${unit.property_id}.docx`;
      await saveFile(key, req.file.buffer, DOCX_MIME, name);
      await pool.query(`UPDATE crm_properties SET hots_template_docx = $1, hots_template_docx_name = $2 WHERE id = $3`, [key, name, unit.property_id]);
      const replaceText = req.body?.replaceText === true || req.body?.replaceText === "true";
      const textSaved = !hasText(unit.hots_template) || replaceText;
      if (textSaved) await pool.query(`UPDATE crm_properties SET hots_template = $1 WHERE id = $2`, [read, unit.property_id]);
      const tokens = knownTokensIn(read).length;
      const { people } = await briefAndPeople(unit.id);
      await logEvent(unit.id, access, people, "template", `uploaded the property's standard Heads of Terms (${name})`, null);
      const note = !textSaved ? "The Word document is saved. The property's standard text was left as it is."
        : tokens === 0 ? "The document has no placeholders, so generated Heads of Terms will copy it as written and the figures must be typed in. Or use Create standard HOTs."
        : null;
      res.json({ ok: true, name, tokens, textSaved, note, workspace: await buildWorkspace(unit.id, access) });
    } catch (e: any) { fail(res, e, "Failed to upload the standard Heads of Terms"); }
  });

  // 3. Generate the unit's HOTs from the agreed offer.
  app.post("/api/unit-hots/:unitId/generate", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { access } = ctx;
      if (!access.canEditTerms) return res.status(403).json({ message: "Joint agents can read and agree the Heads of Terms, not change them" });
      const offerId = req.body?.offerId;
      if (offerId !== undefined && offerId !== null && typeof offerId !== "string") return res.status(400).json({ message: "Pick the offer to generate from" });
      await withUnitLock(ctx.unit.id, async () => {
        const unit = await loadUnit(ctx.unit.id);
        if (!unit) return void res.status(404).json({ message: "That unit is not on the tracker" });
        const stage = stageOf(unit);
        if (stage === "final") return void res.status(409).json({ message: "The final Heads of Terms are uploaded. They are not generated again.", code: "FINAL" });
        if (stage === "issued") return void res.status(409).json({ message: "The Heads of Terms have been issued. Ask BGP to reopen them for amendments first.", code: "ISSUED" });
        let template = text(unit.hots_template);
        // A Word standard uploaded before its text was read: read it now.
        if (!template.trim() && unit.hots_template_docx) {
          const { getFile } = await import("./file-storage");
          const file = await getFile(unit.hots_template_docx).catch(() => null);
          if (file) template = await docxText(file.data).catch(() => "");
        }
        if (!template.trim()) return void res.status(409).json({ message: "This property has no standard Heads of Terms yet. BGP adds the standard first.", code: "NO_TEMPLATE" });
        let offer: any;
        if (offerId) {
          offer = await offerById(offerId);
          if (!offer || offer.unit_id !== unit.id) return void res.status(400).json({ message: "That offer is not on this unit" });
          if (!isAgreedStatus(offer.status)) return void res.status(409).json({ message: "Agree the terms on that offer first", code: "NO_AGREED_OFFER" });
        } else {
          offer = await agreedOfferFor(unit.id);
          if (!offer) return void res.status(409).json({ message: "Agree the terms on an offer first", code: "NO_AGREED_OFFER" });
        }
        const hadDraft = hasText(unit.hots_content);
        if (hadDraft && req.body?.replace !== true) return void res.status(409).json({ message: "This unit already has draft Heads of Terms. Replace them with a fresh copy from the offer?", code: "DRAFT_EXISTS" });
        const { brief, people } = await briefAndPeople(unit.id);
        const { text: filled } = fillHotsTemplate(template, await hotsValuesFor(unit, offer, brief, people));
        if (filled.length > CONTENT_MAX) return void res.status(400).json({ message: "The filled Heads of Terms are too long. Shorten the property's standard." });
        const version = unit.hots_version + 1;
        await pool.query(
          `UPDATE available_units SET hots_content = $2, hots_updated_at = NOW(), hots_version = $3, hots_offer_id = $4, hots_agreed_at = NULL WHERE id = $1`,
          [unit.id, filled, version, offer.id]);
        await logEvent(unit.id, access, people, "generated",
          `${hadDraft ? "replaced the draft with Heads of Terms generated" : "generated the Heads of Terms"} from ${offer.company_name || "the tenant"}'s agreed offer of ${shortDate(offer.offer_date)}`, version);
        res.json(await buildWorkspace(unit.id, access));
      });
    } catch (e: any) { fail(res, e, "Failed to generate the Heads of Terms"); }
  });

  // 4. Amend the draft. Every amendment raises the version, so signatures
  // given on the earlier text stop counting.
  app.put("/api/unit-hots/:unitId/content", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { access } = ctx;
      if (!access.canEditTerms) return res.status(403).json({ message: "Joint agents can read and agree the Heads of Terms, not change them" });
      if (typeof req.body?.content !== "string") return res.status(400).json({ message: "The Heads of Terms must be text" });
      const content = req.body.content.replace(/\r\n/g, "\n");
      if (content.length > CONTENT_MAX) return res.status(400).json({ message: `The Heads of Terms are too long (${num(content.length)} characters). The limit is ${num(CONTENT_MAX)}.` });
      if (!content.trim()) return res.status(400).json({ message: "The Heads of Terms cannot be empty. To start again, generate them from the offer." });
      const baseVersion = Number(req.body?.baseVersion);
      if (!Number.isInteger(baseVersion)) return res.status(400).json({ message: "Say which version you were editing (baseVersion)" });
      await withUnitLock(ctx.unit.id, async () => {
        const unit = await loadUnit(ctx.unit.id);
        if (!unit) return void res.status(404).json({ message: "That unit is not on the tracker" });
        const stage = stageOf(unit);
        if (stage === "final" || stage === "issued") return void res.status(409).json({ message: stage === "final" ? "The final Heads of Terms are uploaded. The draft can no longer be changed." : "The Heads of Terms have been issued. Ask BGP to reopen them for amendments first.", code: stage.toUpperCase() });
        if (!hasText(unit.hots_content)) return void res.status(409).json({ message: "There is no draft yet. Generate the Heads of Terms from the agreed offer first.", code: "NO_DRAFT" });
        if (baseVersion !== unit.hots_version) {
          return void res.status(409).json({ message: "Someone else amended the Heads of Terms while you were editing. Load the latest version, then make your changes again.", code: "STALE", workspace: await buildWorkspace(unit.id, access) });
        }
        const before = text(unit.hots_content).replace(/\r\n/g, "\n");
        if (before === content) return void res.json(await buildWorkspace(unit.id, access));
        const version = unit.hots_version + 1;
        const { people } = await briefAndPeople(unit.id);
        const signed = (await pool.query(
          `SELECT COUNT(*)::int AS n FROM unit_hots_signoffs s WHERE s.unit_id = $1 AND s.version = $2 AND s.brief_person_id = ANY($3::varchar[])`,
          [unit.id, unit.hots_version, people.map(p => p.id)])).rows[0].n;
        await pool.query(`UPDATE available_units SET hots_content = $2, hots_updated_at = NOW(), hots_version = $3, hots_agreed_at = NULL WHERE id = $1`, [unit.id, content, version]);
        await logEvent(unit.id, access, people, "amended",
          `amended the Heads of Terms\n${describeHotsChange(before, content)}${signed ? `\n${signed === 1 ? "The signature" : `The ${signed} signatures`} already given ${signed === 1 ? "is" : "are"} on the earlier version, so sign-off starts again` : ""}`, version);
        res.json(await buildWorkspace(unit.id, access));
      });
    } catch (e: any) { fail(res, e, "Failed to save the Heads of Terms"); }
  });

  // 5. Agree the current version (or take the agreement back). A person
  // agrees as themselves; BGP staff record an agreement only for someone
  // with no login, and the record says who recorded it.
  app.post("/api/unit-hots/:unitId/agree", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { access } = ctx;
      const withdraw = req.body?.withdraw === true;
      const briefPersonId = req.body?.briefPersonId;
      if (briefPersonId !== undefined && briefPersonId !== null && typeof briefPersonId !== "string") return res.status(400).json({ message: "Pick the person who is agreeing" });
      await withUnitLock(ctx.unit.id, async () => {
        const unit = await loadUnit(ctx.unit.id);
        if (!unit) return void res.status(404).json({ message: "That unit is not on the tracker" });
        const { people } = await briefAndPeople(unit.id);
        const person = briefPersonId ? people.find(p => p.id === briefPersonId) : people.find(p => isSelfPerson(p, access));
        if (!person) return void res.status(400).json({ message: briefPersonId ? "That person is not on this unit's brief" : "You are not listed on this unit's brief" });
        const isSelf = isSelfPerson(person, access);
        if (!isSelf && !access.isStaff) return void res.status(403).json({ message: `Only ${person.name} can agree the Heads of Terms as ${person.name}` });
        if (!isSelf && person.user_id) return void res.status(403).json({ message: `${person.name} has a login and agrees for themselves` });
        const stage = stageOf(unit);
        if (stage === "issued" || stage === "final") return void res.status(409).json({ message: stage === "final" ? "The final Heads of Terms are uploaded. Sign-off is closed." : "The Heads of Terms have been issued. Ask BGP to reopen them for amendments first.", code: stage.toUpperCase() });
        if (withdraw) {
          const gone = await pool.query(`DELETE FROM unit_hots_signoffs WHERE unit_id = $1 AND brief_person_id = $2`, [unit.id, person.id]);
          if (gone.rowCount) await logEvent(unit.id, access, people, "withdrawn", isSelf ? "withdrew their agreement" : `withdrew ${person.name}'s agreement`, unit.hots_version);
        } else {
          if (!hasText(unit.hots_content)) return void res.status(409).json({ message: "There are no Heads of Terms to agree yet. Generate them from the agreed offer first.", code: "NO_DRAFT" });
          const seen = Number(req.body?.version);
          if (!Number.isInteger(seen) || seen !== unit.hots_version) return void res.status(409).json({ message: "The Heads of Terms changed. Read the latest version before agreeing.", code: "STALE" });
          // A repeat on the same version keeps the first date.
          const r = await pool.query(
            `INSERT INTO unit_hots_signoffs (unit_id, brief_person_id, version, agreed_at, agreed_by_user_id, agreed_by_name)
             VALUES ($1, $2, $3, NOW(), $4, $5)
             ON CONFLICT (unit_id, brief_person_id) DO UPDATE
                SET version = EXCLUDED.version, agreed_at = EXCLUDED.agreed_at, agreed_by_user_id = EXCLUDED.agreed_by_user_id, agreed_by_name = EXCLUDED.agreed_by_name
              WHERE unit_hots_signoffs.version <> EXCLUDED.version
             RETURNING id`,
            [unit.id, person.id, unit.hots_version, access.userId, access.name]);
          if (r.rowCount) await logEvent(unit.id, access, people, "agreed", isSelf ? "agreed the Heads of Terms" : `recorded ${person.name}'s agreement (${briefRoleLabel(person.role)})`, unit.hots_version);
        }
        await refreshAgreed(unit.id);
        res.json(await buildWorkspace(unit.id, access));
      });
    } catch (e: any) { fail(res, e, "Failed to record the agreement"); }
  });

  // 6. Record the HOTs as issued to the tenant, and move the unit to HOTs.
  // Nothing is emailed from here.
  app.post("/api/unit-hots/:unitId/issue", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { access } = ctx;
      if (!access.isStaff) return res.status(403).json({ message: `${STAFF_ONLY}: BGP issues the Heads of Terms to the tenant` });
      await withUnitLock(ctx.unit.id, async () => {
        const unit = await loadUnit(ctx.unit.id);
        if (!unit) return void res.status(404).json({ message: "That unit is not on the tracker" });
        if (!hasText(unit.hots_content)) return void res.status(409).json({ message: "There are no Heads of Terms to issue yet. Generate them from the agreed offer first.", code: "NO_DRAFT" });
        const stage = stageOf(unit);
        if (stage === "issued" || stage === "final") return void res.json(await buildWorkspace(unit.id, access));
        const { people } = await briefAndPeople(unit.id);
        const signoffs = (await pool.query(`SELECT brief_person_id FROM unit_hots_signoffs WHERE unit_id = $1 AND version = $2`, [unit.id, unit.hots_version])).rows;
        const waiting = people.filter(p => !signoffs.some((s: any) => s.brief_person_id === p.id)).map(p => p.name as string);
        if (waiting.length) return void res.status(409).json({ message: `Still to agree this version: ${listNames(waiting)}. Everyone on the brief agrees the Heads of Terms before they are issued.`, code: "NOT_AGREED", waiting });
        await pool.query(`UPDATE available_units SET hots_issued_at = NOW(), hots_issued_by_name = $2 WHERE id = $1`, [unit.id, access.name]);
        await logEvent(unit.id, access, people, "issued",
          people.length ? `issued the Heads of Terms to the tenant, agreed by ${listNames(people.map(p => p.name as string))}` : "issued the Heads of Terms to the tenant. No one was listed on the brief to sign them off", unit.hots_version);

        // The unit moves to HOTs, the way the tracker's own status edit does:
        // the gate, the row, then the mirror to the deal and the schedules.
        let statusWarning: string | null = null;
        const code = legacyToCode(unit.marketing_status);
        if (!unit.marketing_status || code === "AVA" || code === "NEG") {
          statusWarning = await moveUnitStatus(unit, "HOT", access.userId, "unit_hots.issue");
        }
        res.json({ ...(await buildWorkspace(unit.id, access)), ...(statusWarning ? { statusWarning } : {}) });
      });
    } catch (e: any) { fail(res, e, "Failed to issue the Heads of Terms"); }
  });

  app.post("/api/unit-hots/:unitId/reopen", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { access } = ctx;
      if (!access.isStaff) return res.status(403).json({ message: `${STAFF_ONLY}: BGP reopens issued Heads of Terms` });
      await withUnitLock(ctx.unit.id, async () => {
        const unit = await loadUnit(ctx.unit.id);
        if (!unit) return void res.status(404).json({ message: "That unit is not on the tracker" });
        if (unit.hots_final_file_id) return void res.status(409).json({ message: "The final Heads of Terms are uploaded. Remove the final file before reopening the draft.", code: "FINAL" });
        if (unit.hots_issued_at) {
          await pool.query(`UPDATE available_units SET hots_issued_at = NULL, hots_issued_by_name = NULL WHERE id = $1`, [unit.id]);
          const { people } = await briefAndPeople(unit.id);
          await logEvent(unit.id, access, people, "reopened", "reopened the Heads of Terms for amendments", unit.hots_version);
        }
        res.json(await buildWorkspace(unit.id, access));
      });
    } catch (e: any) { fail(res, e, "Failed to reopen the Heads of Terms"); }
  });

  // 7. The final agreed HOTs, negotiated outside the app.
  app.post("/api/unit-hots/:unitId/final", requireAuth, oneFile([".pdf", ".docx"], 25, "Upload the final Heads of Terms as a PDF or a Word document (.docx)"), async (req: any, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { access } = ctx;
      if (!access.isStaff) return res.status(403).json({ message: `${STAFF_ONLY}: BGP uploads the final agreed Heads of Terms` });
      if (!req.file) return res.status(400).json({ message: "Choose the final Heads of Terms (PDF or .docx) to upload" });
      if (!req.file.size) return res.status(400).json({ message: "That file is empty" });
      const ext = path.extname(req.file.originalname || "").toLowerCase();
      const name = String(req.file.originalname || `Final HOTs${ext}`).slice(0, 200);
      const mime = ext === ".pdf" ? "application/pdf" : DOCX_MIME;
      await withUnitLock(ctx.unit.id, async () => {
        const unit = await loadUnit(ctx.unit.id);
        if (!unit) return void res.status(404).json({ message: "That unit is not on the tracker" });
        // Stored the way the unit's other files are, so it is served, scoped
        // and deleted with them.
        const unique = `${Date.now()}-${crypto.randomBytes(8).toString("hex")}${ext}`;
        await saveFile(`marketing-files/${unique}`, req.file.buffer, mime, name);
        const file = (await pool.query(
          `INSERT INTO unit_marketing_files (unit_id, file_name, file_path, file_type, file_size, mime_type, category)
           VALUES ($1, $2, $3, 'hots_final', $4, $5, 'other') RETURNING id`,
          [unit.id, name, `/uploads/marketing-files/${unique}`, req.file.size, mime])).rows[0];
        await pool.query(`UPDATE available_units SET hots_final_file_id = $2, hots_final_at = NOW(), hots_final_by_name = $3 WHERE id = $1`, [unit.id, file.id, access.name]);
        const { people } = await briefAndPeople(unit.id);
        await logEvent(unit.id, access, people, "final_uploaded", `${unit.final_id ? "replaced the final agreed Heads of Terms with" : "uploaded the final agreed Heads of Terms:"} ${name}`, unit.hots_version || null);
        res.json(await buildWorkspace(unit.id, access));
      });
    } catch (e: any) { fail(res, e, "Failed to upload the final Heads of Terms"); }
  });

  app.delete("/api/unit-hots/:unitId/final", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { access } = ctx;
      if (!access.isStaff) return res.status(403).json({ message: `${STAFF_ONLY}: BGP manages the final agreed Heads of Terms` });
      await withUnitLock(ctx.unit.id, async () => {
        const unit = await loadUnit(ctx.unit.id);
        if (!unit) return void res.status(404).json({ message: "That unit is not on the tracker" });
        if (unit.hots_final_file_id) {
          if (unit.final_id && CONVERTED_CODES.includes(legacyToCode(unit.marketing_status) || "")) {
            return void res.status(409).json({ message: "The deal has been converted to Solicitors, so the final Heads of Terms stay on the record. Upload a corrected file to replace them.", code: "CONVERTED" });
          }
          // The file itself stays in the unit's files; only the pointer goes.
          await pool.query(`UPDATE available_units SET hots_final_file_id = NULL, hots_final_at = NULL, hots_final_by_name = NULL WHERE id = $1`, [unit.id]);
          const { people } = await briefAndPeople(unit.id);
          await logEvent(unit.id, access, people, "final_removed", `removed the final agreed Heads of Terms${unit.final_name ? ` (${unit.final_name})` : ""}`, unit.hots_version || null);
        }
        res.json(await buildWorkspace(unit.id, access));
      });
    } catch (e: any) { fail(res, e, "Failed to remove the final Heads of Terms"); }
  });

  // 8. Convert the letting to Solicitors: the agreed terms go on the deal,
  // the unit and the deal move to SOL, and AML starts.
  app.post("/api/unit-hots/:unitId/convert", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { access } = ctx;
      if (!access.isStaff) return res.status(403).json({ message: `${STAFF_ONLY}: BGP converts the deal to Solicitors` });
      const b = req.body || {};
      const given = (k: string) => b[k] !== undefined && b[k] !== null && b[k] !== "";
      // Validate what was typed before anything is written.
      const figures: Record<string, number> = {};
      for (const [key, label, max] of [["rentPa", "Rent a year", 1e9], ["capitalContribution", "Capital contribution", 1e9], ["leaseLengthYears", "Lease length", 999], ["rentFreeMonths", "Rent free", 600]] as const) {
        if (!given(key)) continue;
        const n = key === "rentPa" || key === "capitalContribution" ? parseMoney(b[key]) : typeof b[key] === "number" ? b[key] : typeof b[key] === "string" && /^\d+(\.\d+)?$/.test(b[key].trim()) ? Number(b[key]) : undefined;
        if (n === undefined || n === null || !Number.isFinite(n) || n < 0 || n > max) {
          return res.status(400).json({ message: key === "rentPa" || key === "capitalContribution" ? `${label} must be a yearly figure as a number, for example 95000 or 95k` : `${label} must be a number${key === "leaseLengthYears" ? " of years" : " of months"}` });
        }
        figures[key] = n;
      }
      if (given("breakOption") && (typeof b.breakOption !== "string" || b.breakOption.length > 500)) return res.status(400).json({ message: "Break option must be text of up to 500 characters" });
      if (given("tenantCompanyId") && typeof b.tenantCompanyId !== "string") return res.status(400).json({ message: "Pick the tenant company from the CRM" });

      await withUnitLock(ctx.unit.id, async () => {
        let unit = await loadUnit(ctx.unit.id);
        if (!unit) return void res.status(404).json({ message: "That unit is not on the tracker" });
        if (!unit.final_id) return void res.status(409).json({ message: "Upload the final agreed Heads of Terms first", code: "NO_FINAL" });
        if (!unit.property_id) return void res.status(400).json({ message: "Link this unit to a property first" });
        const code = legacyToCode(unit.marketing_status);
        // Already at Solicitors or past it: nothing to do, same answer.
        if (code && CONVERTED_CODES.includes(code) && unit.deal_id) {
          const done = await conversionFor(unit, access, code === "SOL" ? null : `The unit is already at ${DEAL_STATUS_LABELS[code] || code}, so nothing was changed.`);
          if (done) return void res.json(done);
        }
        if (code === "WIT" || code === "ARCH") return void res.status(409).json({ message: "This unit is withdrawn. Put it back on the market before converting it to Solicitors.", code: "UNIT_CLOSED" });

        const d = await convertDefaultsFor(unit);
        let tenantCompanyId: string | null = d.tenantCompanyId;
        if (given("tenantCompanyId")) {
          const c = (await pool.query(`SELECT id FROM crm_companies WHERE id = $1`, [b.tenantCompanyId])).rows[0];
          if (!c) return void res.status(400).json({ message: "That tenant company is not in the CRM" });
          tenantCompanyId = c.id;
        }
        const terms: Record<string, any> = {
          tenantId: tenantCompanyId,
          rentPa: figures.rentPa ?? d.rentPa,
          leaseLength: figures.leaseLengthYears ?? d.leaseLengthYears,
          rentFree: figures.rentFreeMonths ?? d.rentFreeMonths,
          breakOption: given("breakOption") ? String(b.breakOption).trim() : d.breakOption,
          capitalContribution: figures.capitalContribution ?? d.capitalContribution,
        };

        // Every tracker row has a backing deal; heal one that has none.
        if (!unit.deal_id) {
          const { ensureBackingDealForUnit } = await import("./unit-mirror");
          const backing = await ensureBackingDealForUnit(pool, unit.id);
          if (!backing) return void res.status(409).json({ message: "This unit has no deal, and one could not be made: a live deal for the same unit sits on another tracker row. Merge the duplicate rows first.", code: "NO_DEAL" });
          unit = await loadUnit(unit.id);
        }
        const dealId: string = unit.deal_id;
        const before = (await pool.query(
          `SELECT id, status, tenant_id, landlord_id, vendor_id, purchaser_id, rent_pa, lease_length, rent_free, break_option, capital_contribution, aml_check_completed FROM crm_deals WHERE id = $1`, [dealId])).rows[0];
        if (!before) return void res.status(409).json({ message: "This unit's deal could not be found. Open the unit on the tracker and give it a deal first.", code: "NO_DEAL" });

        // The gate, for the parties the deal is about to carry: a
        // counterparty the MLRO has rejected stops the move, before any write.
        const { checkCounterpartyAml, amlGateOutcome, dealStatusTransitionDenial } = await import("./deal-gates");
        if (before.aml_check_completed !== "YES") {
          const outcome = amlGateOutcome(await checkCounterpartyAml({
            landlordId: before.landlord_id, tenantId: terms.tenantId || before.tenant_id, vendorId: before.vendor_id, purchaserId: before.purchaser_id }));
          if (outcome.block) return void res.status(409).json({ message: outcome.block, code: "AML_GATE_FAILED" });
        }

        // The agreed terms go on the deal through the deal door: only the
        // ones that have a value, never blanking what is there, never a fee.
        const columns: Record<string, string> = { tenantId: "tenant_id", rentPa: "rent_pa", leaseLength: "lease_length", rentFree: "rent_free", breakOption: "break_option", capitalContribution: "capital_contribution" };
        const patch: Record<string, any> = {};
        for (const k of Object.keys(columns)) {
          const v = terms[k];
          if (v === null || v === undefined || v === "") continue;
          const was = before[columns[k]];
          if (was !== null && was !== undefined && (typeof v === "number" ? Number(was) === v : was === v)) continue;
          patch[k] = v;
        }
        if (Object.keys(patch).length) {
          const { updateDeal } = await import("./letting-service");
          await updateDeal(dealId, patch, { userId: access.userId, source: "deal-form" });
          for (const k of Object.keys(patch)) {
            await pool.query(
              `INSERT INTO deal_audit_log (deal_id, field, old_value, new_value, reason, changed_by, changed_by_name) VALUES ($1, $2, $3, $4, $5, $6, $7)`,
              [dealId, columns[k], before[columns[k]] == null ? null : String(before[columns[k]]), String(patch[k]), "Agreed terms from the final Heads of Terms (unit_hots.convert)", access.userId, access.name],
            ).catch((e: any) => console.warn("[unit-hots] deal audit failed:", e?.message));
          }
        }

        // The gate itself (it records the AML warning against the deal as it
        // now stands), then the unit, then the mirror to the deal and schedules.
        const denial = await dealStatusTransitionDenial(access.userId, dealId, "SOL");
        if (denial) return void res.status(denial.status).json({ message: denial.error, code: denial.code });
        const statusWarning = await moveUnitStatus(unit, "SOL", access.userId, "unit_hots.convert", { gated: true });

        // AML starts for both sides (a no-op while KYC4U is BGP's MLRO).
        try {
          const { autoLaunchAmlForDeal } = await import("./deal-stages");
          await autoLaunchAmlForDeal(dealId, access.userId, access.name);
        } catch (e: any) { console.warn("[unit-hots] AML auto-launch failed:", e?.message); }

        // The offer the HOTs came from is the agreed one.
        if (unit.hots_offer_id) {
          await pool.query(
            `UPDATE unit_offers SET status = 'Agreed', agreed_at = COALESCE(agreed_at, NOW()), agreed_by_user_id = COALESCE(agreed_by_user_id, $2), agreed_by_name = COALESCE(agreed_by_name, $3), updated_at = NOW()
              WHERE id = $1 AND unit_id = $4 AND NOT (${AGREED_OFFER_SQL})`, [unit.hots_offer_id, access.userId, access.name, unit.id]);
        }

        const after = await loadUnit(unit.id);
        const out = await conversionFor(after, access, statusWarning);
        const { people } = await briefAndPeople(unit.id);
        await logEvent(unit.id, access, people, "converted",
          `converted the deal to Solicitors${after.deal_ref != null ? ` (deal #${after.deal_ref})` : ""}${out?.tenantName ? `, tenant ${out.tenantName}` : ""}${terms.rentPa != null ? `, rent ${gbp(terms.rentPa)} a year` : ""}`, unit.hots_version || null);
        res.json(out);
      });
    } catch (e: any) { fail(res, e, "Failed to convert the deal to Solicitors"); }
  });

  // The draft as a document, for anyone who can read it (the tracker's older
  // download routes are closed to Landsec asset managers and joint agents).
  app.get("/api/unit-hots/:unitId/download", requireAuth, async (req, res) => {
    try {
      const ctx = await openUnit(req, res);
      if (!ctx) return;
      const { unit } = ctx;
      const content = text(unit.hots_content);
      if (!content.trim()) return res.status(404).json({ message: "There are no Heads of Terms on this unit yet" });
      const format = req.query.format === "docx" ? "docx" : "pdf";
      const base = safeName(`HOTs - ${unit.property_name || "Property"} - ${unit.unit_name || "Unit"} - v${unit.hots_version}`);
      const heading = [unit.unit_name, unit.property_name].filter(Boolean).join(", ");
      if (format === "docx") {
        const { Document, Packer, Paragraph, TextRun } = await import("docx");
        const doc = new Document({
          styles: { default: { document: { run: { font: "Calibri", size: 22 } } } },
          sections: [{ children: content.split("\n").map(line => new Paragraph({ spacing: { after: 80 }, children: [new TextRun({ text: line, bold: /^\d+\.\s/.test(line) || line === "HEADS OF TERMS" })] })) }],
        });
        res.setHeader("Content-Type", DOCX_MIME);
        res.setHeader("Content-Disposition", contentDispositionFor(`${base}.docx`));
        return void res.send(Buffer.from(await Packer.toBuffer(doc)));
      }
      const PDFDocument = (await import("pdfkit")).default;
      const doc = new PDFDocument({ margin: 56, size: "A4" });
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", contentDispositionFor(`${base}.pdf`));
      doc.pipe(res);
      // The document palette (docs/DESIGN.md §1): Bordeaux and Ink.
      doc.fontSize(9).fillColor("#6E0C25").text("SUBJECT TO CONTRACT", { align: "right" });
      doc.moveDown(0.5);
      doc.fontSize(16).fillColor("#6E0C25").text("Heads of Terms");
      if (heading) doc.fontSize(10).fillColor("#1D1D1B").text(heading);
      doc.moveDown();
      doc.fontSize(10).fillColor("#1D1D1B").text(content, { lineGap: 3 });
      doc.moveDown(2);
      doc.fontSize(8).fillColor("#1D1D1B").text(`Bruce Gillingham Pollard. Version ${unit.hots_version}, ${longDate(new Date())}.`);
      doc.end();
    } catch (e: any) { fail(res, e, "Failed to make the document"); }
  });
}

// Set the unit's marketing status the way the tracker's own status edit
// does: the deal gate first, then the row, then the mirror (which moves the
// deal with an audit row, the Leasing Schedule and the tenancy schedule).
// Returns a warning when the status could not be moved or the deal did not
// follow; never throws, because the HOTs step it follows already stands.
async function moveUnitStatus(unit: any, code: "HOT" | "SOL", actorUserId: string | null, reason: string, opts: { gated?: boolean } = {}): Promise<string | null> {
  const label = DEAL_STATUS_LABELS[code] || code;
  try {
    let dealId: string | null = unit.deal_id || null;
    if (!dealId) {
      const { ensureBackingDealForUnit } = await import("./unit-mirror");
      dealId = (await ensureBackingDealForUnit(pool, unit.id).catch(() => null))?.dealId || null;
    }
    if (dealId && !opts.gated) {
      const { dealStatusTransitionDenial } = await import("./deal-gates");
      const denial = await dealStatusTransitionDenial(actorUserId, dealId, code);
      if (denial) return `The unit was not moved to ${label}: ${denial.error}`;
    }
    await storage.updateAvailableUnit(unit.id, { marketingStatus: code });
    try {
      const { mirrorFromAvailableUnit } = await import("./lease-status-mirror");
      await mirrorFromAvailableUnit(unit.id, code, { pool, reason, actorUserId });
    } catch (e: any) {
      return `The unit is at ${label}, but syncing the Deals board and the Leasing Schedule failed (${e?.message || "unknown error"}). The other boards may briefly disagree.`;
    }
    if (dealId) {
      const now = (await pool.query(`SELECT status FROM crm_deals WHERE id = (SELECT deal_id FROM available_units WHERE id = $1)`, [unit.id])).rows[0];
      if (now && legacyToCode(now.status) !== code) {
        const why = (await pool.query(`SELECT reason FROM deal_audit_log WHERE deal_id = $1 AND field = 'status' ORDER BY created_at DESC, id DESC LIMIT 1`, [dealId])).rows[0]?.reason;
        return `The unit is at ${label}, but its deal did not follow${why ? `: ${why}` : ""}.`;
      }
    }
    return null;
  } catch (e: any) {
    return `The unit's status could not be moved to ${label} (${e?.message || "unknown error"}). Set it on the tracker.`;
  }
}
